from pydantic_core import core_schema
from typing import Any

class CustomType:
    @classmethod
    def __get_pydantic_core_schema__(cls, source_type: Any, handler):
        def validate_from_python(value):
            if not isinstance(value, str):
                raise ValueError('Expected string')
            return value.upper()

        def validate_from_json(value):
            if not isinstance(value, str):
                raise ValueError('Expected string')
            return value.lower()

        return core_schema.json_or_python_schema(
            json_schema=core_schema.no_info_plain_validator_function(validate_from_json),
            python_schema=core_schema.no_info_plain_validator_function(validate_from_python)
        )

class Item(BaseModel):
    data: CustomType

i = Item(data='Hello')
print(i.data)

